    bars = []
    for r in (0, h - 1):
        vals = [grid[r][c] for c in range(w) if grid[r][c] != bg]
        if vals:
            color = max(set(vals), key=vals.count)
            cols = [c for c in range(w) if grid[r][c] == color]
            if len(cols) > 1:
                bars.append((r, color, cols))
    if len(bars) < 2:
        return out
    bar_color = bars[0][1]
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != bar_color]
    fill = grid[marks[0][0]][marks[0][1]] if marks else None
    if fill is None:
        return out
    width = len(marks)
    for r,c in marks:
        out[r][c] = 4
    for r,color,cols in bars:
        use = cols[-width:]
        if r == 0:
            stop = max([rr for rr,cc in marks if cc in use], default=-1)
            for rr in range(1, stop+1 if stop >= 0 else h):
